		root.append(element("p", `恢复申请：${recovery.recovery_id}`));
		root.append(element("p", `状态：${stateLabel[recovery.state] || "状态待核对"}`));
		if (recovery.not_before) root.append(element("p", `最早可完成时间：${new Date(recovery.not_before).toLocaleString()}`));
